/**
 * One provider entry from a `PAY.md` file. `fqn` is the provider's
 * fully-qualified name: one or two path segments relative to the registry
 * root (e.g. `buy/demo-quotes`), and must equal the frontmatter `name`.
 */
export type ProviderEntry = {
    fqn: string;
    name: string;
    title: string;
    description: string;
    category: string;
    /**
     * Extra lowercase search terms (`social`, `flights`, …). Optional: `search`
     * matches them, so a query can find a provider whose curated category does
     * not contain the word a caller would naturally type.
     */
    aliases?: string[];
    /**
     * Listing maturity. `experimental` marks an early-stage third-party seller
     * that buy has not reviewed: surfaces that show the entry tag it so a
     * caller confirms before paying. Absent means a regular listing.
     */
    stage?: 'experimental';
    serviceUrl: string;
    payment: {
        schemes: string[];
        networks: string[];
        assets: string[];
    };
    /** Prose markdown body after the frontmatter. */
    body: string;
};
/**
 * What every surface says about a `stage: experimental` entry, so the CLI and
 * the MCP server warn in the same words.
 */
export declare const EXPERIMENTAL_NOTICE: string;
export type Registry = {
    dir: string;
    /** All valid provider entries, sorted by fqn. */
    providers: ProviderEntry[];
};
/**
 * Parse and validate one PAY.md document. `fqn` is the provider's path-based
 * name; throws with a descriptive message on any validation failure.
 */
export declare function parsePayDoc(content: string, fqn: string): ProviderEntry;
/**
 * Load every `PAY.md` under `dir`, at one or two path segments of depth
 * (`<fqn>/PAY.md` or `<org>/<name>/PAY.md`). Any malformed entry aborts the
 * load — the registry is curated, so a broken entry is an authoring error,
 * not runtime data to tolerate.
 */
export declare function loadRegistry(dir: string): Promise<Registry>;
/** Exact fqn lookup (`buy/demo-quotes`). */
export declare function get(registry: Registry, fqn: string): ProviderEntry | undefined;
/** Case-insensitive substring search over fqn, title, description, category, and aliases. */
export declare function search(registry: Registry, query: string): ProviderEntry[];
